import { execute as nodeInsertService } from "./Node/service/NodeInsertService";
import { execute as nodeDisposeService } from "./Node/service/NodeDisposeService";
/**
 * @description テクスチャパッキングのノードクラス
 *              Node class for texture
 *
 * @class
 * @public
 */
export class Node {
    /**
     * @param {number} x
     * @param {number} y
     * @param {number} w
     * @param {number} h
     * @constructor
     * @public
     */
    constructor(index, x, y, w, h) {
        /**
         * @description パッキングされたテクスチャの識別番号
         *              Identification number of packed texture
         *
         * @type {number}
         * @public
         */
        Object.defineProperty(this, "index", {
            enumerable: true,
            configurable: true,
            writable: true,
            value: void 0
        });
        /**
         * @description パッキングされたテクスチャのx座標
         *              x coordinate of packed texture
         *
         * @type {number}
         * @public
         */
        Object.defineProperty(this, "x", {
            enumerable: true,
            configurable: true,
            writable: true,
            value: void 0
        });
        /**
         * @description パッキングされたテクスチャのy座標
         *              y coordinate of packed texture
         *
         * @type {number}
         * @public
         */
        Object.defineProperty(this, "y", {
            enumerable: true,
            configurable: true,
            writable: true,
            value: void 0
        });
        /**
         * @description パッキングされたテクスチャの幅
         *              Width of packed texture
         *
         * @type {number}
         * @public
         */
        Object.defineProperty(this, "w", {
            enumerable: true,
            configurable: true,
            writable: true,
            value: void 0
        });
        /**
         * @description パッキングされたテクスチャの高さ
         *              Height of packed texture
         *
         * @type {number}
         * @public
         */
        Object.defineProperty(this, "h", {
            enumerable: true,
            configurable: true,
            writable: true,
            value: void 0
        });
        /**
         * @description 左のノード
         *              Left node
         *
         * @type {Node}
         * @public
         */
        Object.defineProperty(this, "left", {
            enumerable: true,
            configurable: true,
            writable: true,
            value: void 0
        });
        /**
         * @description 右のノード
         *              Right node
         *
         * @type {Node}
         * @public
         */
        Object.defineProperty(this, "right", {
            enumerable: true,
            configurable: true,
            writable: true,
            value: void 0
        });
        /**
         * @description 使用済みフラグ
         *              Used flag
         *
         * @type {boolean}
         * @public
         */
        Object.defineProperty(this, "used", {
            enumerable: true,
            configurable: true,
            writable: true,
            value: void 0
        });
        this.index = index;
        this.x = x;
        this.y = y;
        this.w = w;
        this.h = h;
        this.left = null;
        this.right = null;
        this.used = false;
    }
    /**
     * @description ノードにテクスチャを挿入、挿入したノードを返却します。
     *              Insert a texture into the node and return the inserted node.
     *
     * @param  {number} width
     * @param  {number} height
     * @return {Node | null}
     * @method
     * @public
     */
    insert(width, height) {
        return nodeInsertService(this, width, height);
    }
    /**
     * @description ノードを削除します。
     *              Remove the node.
     *
     * @return {boolean}
     * @method
     * @public
     */
    dispose(x, y, width, height) {
        return nodeDisposeService(this, x, y, width, height);
    }
}
